"""Individually authored personal-agent and knowledge-workbench profiles."""
from profile_expansions import add

add("C05",
    principle="Cherry Studio 希望把多模型、多资料与不同工作角色集中在一个桌面入口。用户可以比较回答，也可以选择实际执行任务的代理后端。二者不能混同：让三个模型各写一篇文章只是多份答案，真正分工还需要共同目标、状态交接与结果整合。统一工作台的便利主要在组织和切换，而不意味着底层能力完全一致。",
    flow=["Electron 桌面界面\n助手、资料与 Agent 会话", "主进程 AI／会话服务\n流、排队和生命周期", "对话 Provider／代理驱动\nClaude、Pi、DSH 等路线", "持久会话与成果\n展示、恢复及审阅", "后端提供的工具环境\n文件、命令和外部能力", "当前驱动的执行循环\n权限与模型由后端决定"],
    mechanism="界面通过进程间通信请求主进程服务，主进程管理输出与持久状态。Agent Session 的宿主负责排队、生命周期和恢复标记，具体驱动负责连接执行后端。这就像同一工作台可以接不同发动机：工作台能统一显示进度，却不能凭空让所有发动机获得相同工具和恢复语义。切换后端时，除模型外还要核对认证、目录和权限。",
    rows=[("桌面组织", "模型、助手、资料与任务集中管理", "方便整理，但要明确资料属于哪项任务"), ("普通对话", "可比较多个模型的回答", "多个答案不自动构成协作或相互验证"), ("Agent 宿主", "排队、持久化与会话生命周期", "界面有历史不代表执行后端已恢复全部状态"), ("代理驱动", "连接 Claude、Pi、DSH 等后端", "模型、工具和权限依驱动分别核对"), ("数据路径", "桌面、模型服务及工具后端", "本地界面不能证明全部资料留在本机"), ("迁移", "资料、会话与代理配置分层", "迁出前检查文件与历史是否真正可复用")],
    steps=["安装桌面端，先配置一个模型与一个资料主题，验证对话、引用和导出；不必一次导入所有个人文件。", "为常见工作建立职责明确的助手，说明输出要求；用同一材料比较模型时，保持提示和验收一致。", "需要执行任务时创建明确工作空间，选择 Agent 驱动，完成该后端的认证和模型配置。", "让它生成一个真实文件，检查工具、权限和保存位置；中断后恢复一次，确认宿主记录与后端状态衔接正确。", "再尝试第二个驱动，记录能力差异。把不能自动迁移的规则、历史和授权列出来，避免只凭统一界面判断兼容。"],
    command="text\n两种用法分别记录：\n多模型比较：同材料、同提示、各自回答，再人工核验。\nAgent 任务：选驱动、选工作目录、确认认证与工具，再执行。\n记录完整组合：Cherry＋驱动＋模型＋启用工具。",
    task="用给定资料生成一份调研简报，先比较两种模型的提纲，再选择一个 Agent 后端制作最终文件，保留引用和待确认事项。",
    acceptance="比较阶段检查观点和依据，不能按文风投票决定事实；执行阶段检查文件、格式和引用是否真正保存。驱动切换后尤其注意工具和权限是否变化。",
    tradeoff="适合中文多模型用户、资料整理和希望统一桌面入口的人。优势是集中管理，代价是后端组合仍需要理解。只需简单写作可以选 Chatbox；需要多人门户可以看 Open WebUI／LibreChat；想直接控制执行循环则更适合原生代理。")

add("C06",
    principle="Open WebUI 常作为团队或个人的统一模型入口。它把用户、历史、知识与工具放在同一个网页服务里，可以连接本地模型，也可以连接云端。自托管使界面和部分数据可由自己管理，但完整数据路径还包括生成模型、嵌入、检索、搜索和工具，不能因为入口在内网就认定全链路离线。",
    flow=["浏览器与用户账户\n问题、资料及任务", "后端中间层与权限\n消息、知识和工具组装", "模型／嵌入服务\n本地或远端端点", "历史与引用结果\n保存并返回用户", "检索／工具／可选终端\n按部署提供能力", "模型与工具循环\n根据用户权限调用"],
    mechanism="用户提问时，后端决定哪些资料片段与工具可以进入当前上下文，再把它们交给模型。嵌入模型把资料转成便于检索的表示，生成模型负责根据找回的内容回答，两者可以在不同地方运行。增加终端执行后又多了一层进程与文件边界；如果所有用户共用同一个高权限环境，仅有网页登录并不能实现工具隔离。",
    rows=[("统一入口", "用户、模型、历史和知识管理", "多人使用需明确角色与资料可见范围"), ("知识检索", "后端组织相关材料", "用已知答案测试引用，不只看文风"), ("模型部署", "本地或兼容云服务", "生成与嵌入端点分别核对"), ("外部工具", "MCP／OpenAPI 等接入路线", "工具授权需匹配调用用户"), ("执行扩展", "可接终端等能力", "检查用户间文件、进程和凭据隔离"), ("服务维护", "自托管入口与持久数据", "备份、升级、配额和监控属于日常成本")],
    steps=["按官方部署指南启动单人实例，先只连接一个模型，验证对话和历史；关闭本次用不到的执行扩展。", "导入一组主题清楚的资料，配置嵌入和检索，用五到十个有标准答案的问题检查引用与遗漏。", "准备多人使用时再配置账户、角色和知识权限，用不同用户测试能否看到不属于自己的资料。", "每增加一个工具检查授权身份、数据出口和返回内容；加入终端前单独设计文件与进程隔离。", "安排备份与升级验证。要求离线时逐项检查模型、嵌入、搜索、语音、遥测和工具，而不仅是网页地址。"],
    command="text\n数据路径清单：\n网页服务在哪里？历史存在哪里？\n生成模型和嵌入模型在哪里？\n搜索、语音、工具及终端会访问哪里？\n用不同用户测试：资料是否隔离、工具以谁的身份运行。",
    task="为团队建立内部操作手册问答入口。回答必须引用当前手册；资料不足时说明缺口，不得猜测权限、流程和负责人。",
    acceptance="用旧版与新版流程、相似产品名和越权资料提问，检查引用是否准确且符合账户范围。模型更强不一定能补救检索错误；多人产品还必须检查资料隔离与工具身份。",
    tradeoff="适合内网知识入口、共享模型服务和本地模型试用。优势是部署控制，代价是服务与权限治理。个人偶尔问答可以用桌面客户端；复杂软件开发应比较专门编码代理；固定业务自动化则更适合显式流程平台。")

add("C07",
    principle="LibreChat 将熟悉的对话产品与可配置 Agent 结合，适合团队自建统一入口。用户系统、历史、模型、工具和 Agent Builder 在同一服务中组织，但共享一个 Agent 不等于共享所有人的权限。设计团队助理时，最重要的问题是资料从哪里来、工具以谁的身份执行、谁可以修改职责与配置。",
    flow=["网页用户与 Agent Builder\n任务和角色配置", "服务端会话与运行创建\n模型、消息、工具和摘要", "Provider／Agent 执行包\n具体模型与运行能力", "历史、追踪及结果\n返回对应用户", "工具、代码执行、子代理\n按配置接入", "运行生命周期管理\n调用、交接和结束"],
    mechanism="服务端把模型、消息、工具与子代理配置交给执行包，再衔接会话与追踪。它不只是 HTTP 转发，但单个仓库中的封装也不等于底层依赖全被审计。共享 Agent 的配置与调用凭据尤其需要分开：某人能调用“销售助理”，不能据此推定他可以使用创建者的全部业务账户。用只读 Agent 起步，有助于先把知识与身份关系理顺。",
    rows=[("对话产品", "多用户、历史与多个 Provider", "历史和资料需要按用户及共享规则管理"), ("Agent Builder", "配置职责、模型和工具", "职责应包含来源和完成条件，不只是人格描述"), ("运行层", "服务端衔接独立执行包", "审计边界要包含所依赖模块，不能只看导入语句"), ("分工", "可配置子代理／多代理等能力", "明确输入、交接和最终核验责任"), ("凭据", "用户凭据与共享 Agent 配置有不同范围", "逐项验证工具实际使用哪个账户"), ("运维", "服务、数据库和历史保存", "部署之外还需备份、升级及失败诊断")],
    steps=["按官方部署文档准备服务、数据库与模型入口，先建立单用户可用基线并验证历史保存。", "创建一个只读研究 Agent，限定资料来源和输出格式；先不接会写入外部系统的工具。", "用两个用户测试共享和私有资料，以及 Agent 配置的查看、修改与调用权限；核对实际工具身份。", "确需复杂任务再加入代码执行或子代理，要求保存可复查证据并控制资源；同一输入重跑时观察结果和副作用。", "团队推广前安排备份、模型变更与权限回归。服务失败时从模型请求、工具执行和持久化三层分别定位。"],
    command="text\n共享 Agent 配置检查：\n职责与来源 → 可调用模型 → 可用工具\n谁可使用／谁可修改 → 工具使用谁的凭据\n历史与产物归谁 → 错误如何追踪和恢复",
    task="建立一个团队研究助理，只根据指定资料回答产品问题；遇到证据冲突列出来源，需要计算时保存计算方法，不直接改写业务系统。",
    acceptance="除了回答质量，用不同用户核对可见范围与凭据。检查 Agent 是否为没有答案的问题编造结论，子代理的引用能否回到原文，以及服务中断后历史和结果是否一致。",
    tradeoff="适合有部署能力、想统一多个模型和业务 Agent 的团队。代价是数据库、权限与扩展维护。与 Open WebUI 比较具体 Agent 配置与知识流程；与 LobeHub 比较协作组织与使用习惯，不必仅按模型数量判断。")

add("C08",
    principle="LobeHub 将助手、资料与有状态任务放在协作工作台中。一个角色可以负责研究，另一个负责写作，但真正的协作需要共享目标、可查证据和明确交接；不同名字与头像并不会自动形成分工。它适合希望把多种工作职责集中管理的人，同时要求用户避免过度创建角色造成信息分散。",
    flow=["工作台与角色入口\n任务、资料与用户", "服务端协调器\n管理运行生命周期", "Agent 的模型配置\n产生下一步指令", "状态合并及任务成果\n协作与审阅", "工具／人工审批等动作\n实际执行结果", "AgentRuntime\n执行调用、分派和结束"],
    mechanism="运行时把代理产生的指令转成具体动作，例如调用模型、使用工具、请求人工审批或结束。批量工具可以从同一份基础上下文出发再合并结果，这提高独立查询的效率；如果两项动作都要修改同一业务对象，仅有并发机制无法保证语义一致。角色设计应从任务边界出发：是否真的需要不同状态、工具和权限，还是只需换一个提示模板。",
    rows=[("角色组织", "Agent 与协作工作台", "角色要有职责和交付件，不只换人设"), ("有状态运行", "指令与实际执行分开", "完成状态要能对应真实产物"), ("批量工具", "从基础状态执行并汇总结果", "独立查询可并行，冲突写入需额外设计"), ("人工参与", "运行时支持审批动作", "明确何时需要人的判断及判断材料"), ("模型", "按 Provider 与角色配置", "多模型结论一致也可能源自同一错误材料"), ("部署", "托管与自托管路线", "多人权限和数据保存按实际部署核对")],
    steps=["先用一个职责明确的 Agent，例如仅基于团队资料回答问题，配置模型、知识来源和必要工具。", "用已知答案检查材料引用和结果；记录任务状态与输出在哪里保存，确认以后能够追溯。", "任务确实有不同职责时再增加角色，给出输入、输出和交接规则。例如研究交回证据表，写作根据证据表成文。", "并行工具只用于真正独立的动作；涉及写入同一对象时安排顺序或统一负责人，避免冲突后靠语言总结掩盖。", "多人使用时检查角色配置修改权、资料范围及产物归属；模型或服务升级后重做一条完整工作流。"],
    command="text\n两角色协作示例：\n研究角色：输出事实、来源、冲突与不确定项\n写作角色：依据证据表生成正文，不添加未证实事实\n最终核验：逐项检查正文结论是否有来源支撑\n角色增加必须对应真实工作边界。",
    task="把一组市场材料整理成产品简报。先由研究职责形成证据表，再按该表写正文；最后检查观点、数据和来源是否一一对应。",
    acceptance="检查两个角色是否真的交接证据，而不是各写一遍近似答案。不同模型若用了同一份错误摘要，不能算独立复核；应回到原材料抽查关键数据和冲突观点。",
    tradeoff="适合希望集中管理资料、角色与协作任务的个人和团队。代价是角色、共享状态和权限设计。简单任务保留一个 Agent 往往更清楚；固定业务流程可以比较 Dify，需要随时从消息渠道工作则可比较 OpenClaw。")

add("C09",
    principle="AnythingLLM 围绕一批固定资料持续工作。用户先建立工作空间，把文档处理和检索准备好，再反复提问或运行资料流程。这特别适合手册、政策、项目档案和长期研究材料。它的效果不仅由回答模型决定，文档是否正确提取、切片和检索，常常更早决定答案是否可靠。",
    flow=["桌面／网页工作空间\n资料与问题", "解析、嵌入与检索\n形成相关片段", "生成模型\n依据材料作答或选工具", "引用、对话和输出\n保存与复查", "Agent 工具／Flow 步骤\n按配置执行", "Agent／Flow 执行器\n自治循环或确定流程"],
    mechanism="导入文档后先提取内容，再形成适合检索的表示；提问时只找回相关片段交给生成模型。因此，“资料已经上传”不表示回答时真的看到了关键段落。Agent 可以根据任务选择动作，Flow 则按预先设置的步骤传递变量和处理结束条件。前者更灵活，后者更容易重复，应该按任务是否固定来选择。",
    rows=[("资料工作空间", "围绕主题组织文档", "主题与权限边界清楚，检索更容易验收"), ("检索链", "解析、嵌入、向量检索和生成分层", "先查资料是否正确提取，再考虑换生成模型"), ("引用", "回答应能回到原始片段", "引用存在不等于足以支持整句结论"), ("Agent", "工具与任务循环", "适合步骤不完全确定的资料任务"), ("Flow", "步骤、变量与错误／输出条件", "适合重复提取与固定处理流程"), ("部署", "桌面与多人服务能力不同", "共享、权限和备份按实际版本设计")],
    steps=["选择桌面或服务部署，创建单一主题工作空间，先导入少量整理好的材料，确认文本提取完整。", "配置生成与嵌入服务，记录各自位置；用五到十个有标准答案的问题测试检索、引用和资料缺失时的表现。", "遇到答错先检查原文是否读入、检索是否命中，再检查模型理解。不要首先靠升级大模型掩盖材料问题。", "需要重复操作时设计小 Flow，明确输入变量、输出格式和失败分支；不确定步骤较多时再试 Agent 工具。", "长期使用建立资料更新和去旧流程。多人服务额外测试工作空间权限、数据备份与新旧版本冲突。"],
    command="text\n知识库排错顺序：\n原文正确吗 → 文本提取完整吗 → 关键片段检索到了吗\n→ 模型是否忠实理解 → 引用是否支持结论\n换嵌入服务时，还要核对已有索引是否需要重建。",
    task="根据内部手册回答报销流程问题，明确不同费用类型与例外条件。手册没有说明的内容标为待确认，不以常识代替组织规定。",
    acceptance="用跨章节、旧版与新版、存在例外和根本没答案的问题测试。看它能否指出资料缺口并给出准确出处，而不是把相似段落拼成听起来合理的新规则。",
    tradeoff="适合固定材料问答、项目文档库和可重复资料处理。临时写作可能用普通客户端更省事，复杂多系统业务可以用 n8n／Dify。模型选型之前先验收检索，否则更强模型通常只会把错误表达得更流畅。")

add("C01",
    principle="Hermes 更关注长期使用而非单次回答。一次任务留下的经验、偏好与方法，可以在下一次被重新读取。其价值取决于保存的信息是否正确、是否能找回来以及是否及时修订。它适合有连续项目与重复工作的人；偶尔聊天的人未必需要承担多渠道和持续服务的配置成本。",
    flow=["CLI／消息渠道／定时入口\n任务与身份", "上下文及记忆准备\n历史检索、Skills、偏好", "Provider 与模型\n当前任务的推理", "会话、记忆与经验材料\n保存供后续使用", "工具和独立子代理\n执行、研究、汇总", "Python 会话循环\n动作、纠错与终止"],
    mechanism="长期信息不应都塞进同一段提示。偏好描述你一般怎样工作，项目事实描述某个项目目前是什么样，Skill 描述一套可复用的方法，当前进度则记录这一项任务做到了哪里。Hermes 的记忆 Provider 和会话循环为这些材料提供保存与使用路径，但内容治理仍然重要。子代理拥有自己的上下文与预算，主任务得到汇总，因此要明确哪些结论值得长期保存，不能把未经核对的探索猜测直接变成记忆。",
    rows=[("长期材料", "记忆、历史检索与 Skills", "经验复用依赖正确保存和命中，不是训练权重"), ("压缩", "上下文处理与压缩前的信息保存", "关键事实应有可读出处，便于恢复核对"), ("委派", "独立代理、可选模型及工作树", "任务描述需包含交付格式和证据要求"), ("预算", "子任务可以拥有自己的上限", "父任务预算不自动等于整棵任务树总额"), ("入口", "CLI、消息和自动化等路线", "长期在线增加身份、服务与凭据管理"), ("记忆治理", "材料可积累，也需要修正", "明确哪些是偏好、事实、临时判断与过期信息")],
    steps=["先按官方指南只配置本地 CLI 与一个模型，用一份资料整理任务验证工具、输出和保存位置。", "给代理明确项目材料与引用要求，让它生成报告；检查事实后再决定哪些经验适合写入长期记忆或 Skill。", "开启新会话询问上次任务，检查它是否能找到正确资料并保留来源；故意更新一项事实，验证旧信息怎样被修正。", "独立研究较多时再委派子任务，规定输入、输出和预算，汇总时检查证据冲突及总成本。", "最后才接消息渠道和定时工作。验证触发者身份、任务运行环境与结果投递，并安排对记忆和失败任务的定期检查。"],
    command="text\n建议分开保存四种材料：\n长期偏好：我的报告习惯与表达要求\n项目事实：术语、状态、来源及更新时间\n方法：可复用的资料核对步骤\n当前进度：已完成、失败原因、下一步",
    task="每次根据新访谈补充同一份研究档案，保留来源和冲突观点。记住报告格式偏好，但不要把未证实的市场判断写成永久事实。",
    acceptance="做两次相隔的任务，才能观察长期价值。检查第二次是否准确找回既有材料，是否知道哪些事实已改变，以及能否解释来源。记得很多却无法纠错，比少记一些且依据清楚更难维护。",
    tradeoff="适合持续研究、个人自动化和从重复工作积累方法。代价主要在记忆质量、多入口身份与长期运行。与编码 CLI 比较时看跨会话收益；与 OpenClaw 比较时，一个更突出经验与方法复用，另一个更突出渠道、设备与持续连接。")

add("C02",
    principle="OpenClaw 把个人代理做成持续在线的连接中心。来自手机、桌面与消息渠道的任务需要进入正确会话，再交给运行时执行。它解决的是“无论从哪里发起，怎样找到自己的工作状态”，而不是单纯多开几个聊天界面。持续连接带来便利，也要求清楚识别用户、设备和触发权限。",
    flow=["设备与消息渠道\n经过配对的输入", "Gateway\n连接、身份与会话路由", "所选代理运行时／模型\n按后端配置", "持久状态与消息返回\n确认写入资格", "工具与工作空间\n宿主或显式隔离环境", "会话队列与代理循环\n串行化及取消管理"],
    mechanism="Gateway 类似接线台，负责把输入放进正确会话；代理运行时才决定下一步动作。同一会话通常需要串行处理，避免两次任务同时修改同一份状态。旧任务被替换后，持久化写入还要确认它是否仍有资格写回，否则可能覆盖新任务的正确结果。记忆文件、检索和整理提供长期连续性，但过时信息仍需要用户纠正。",
    rows=[("连接中心", "Gateway 管渠道、设备与会话", "先验证谁能发指令，再开放更多入口"), ("执行后端", "多种运行时路径", "后端决定模型、工具及部分权限行为"), ("并发状态", "会话串行与写入资格控制", "避免旧任务覆盖新状态，关注取消后的行为"), ("记忆", "工作空间材料、摘要、检索与整理", "要能查看、更正和删除，而非只积累"), ("工具环境", "宿主执行与显式沙箱分开", "自托管不等于工具天然隔离"), ("持续运行", "多渠道和自动化依赖服务在线", "备份、升级、失败恢复也是使用成本")],
    steps=["准备一个可维护的运行环境，按官方指南部署 Gateway；先只配一个设备或渠道，完成身份与连接检查。", "选择代理后端和模型，确认工作空间、工具范围与执行环境。先做只读资料任务，核对结果回到正确会话。", "连续发送两条有顺序的任务，观察队列、取消与状态保存；不要假定多个渠道意味着任务可以随意并发修改同一文件。", "配置长期记忆后测试事实更新与删除，保留重要项目材料的备份；确认新会话使用的是最新信息。", "再增加渠道或定时触发，逐项检查触发者、凭据、运行位置和失败恢复。服务升级后重复基本配对与工具测试。"],
    command="text\n持续服务检查顺序：\n用户与设备身份 → 会话路由 → 执行后端 → 工具环境\n→ 状态写入与恢复 → 消息返回 → 定时触发\n每新增一个入口，都重查身份与结果归属。",
    task="从消息渠道提交一份资料摘要任务，随后补充修订要求；代理应在同一项目中更新报告，并把新版本返回原会话，保留资料来源。",
    acceptance="观察后发的修订是否被正确纳入、旧任务是否覆盖新文件，以及结果是否发到正确对象。单次聊天成功无法验证持续服务；中断恢复和跨渠道状态才是这条路线的重要试用点。",
    tradeoff="适合愿意维护个人服务、需要跨设备和消息入口的人。代价是部署、身份、权限与状态管理。若只是本地写报告，Chatbox／Cherry 更轻；若重点在可重复业务流程，n8n 的显式流程可能更容易观察和管理。")

add("C03",
    principle="Agent Zero 把模型放进能实际操作的计算环境，使它可以写程序处理资料、调用工具并分派工作。它更像通用技术助理实验台：适应任务的方式很多，用户也能修改提示和工具。自由度越高，越需要清楚提供资料范围、输出要求与可操作环境，否则模型容易花很多时间探索而没有形成可用结果。",
    flow=["Web／任务入口\n资料与目标", "代理配置和提示\n角色、工作空间、规则", "模型 Provider\n规划与工具选择", "结果、历史及干预\n汇总后继续", "计算环境与工具\n文件、程序及服务", "主循环和下属代理\n扩展事件与任务分派"],
    mechanism="主循环在准备提示、调用模型、处理工具等位置允许扩展介入，适合试验不同工作方法。下属代理拥有自己的配置与任务，主代理负责交接和汇总。容器给任务提供相对独立的环境，但挂载目录和外部凭据仍决定它能影响什么。最实用的验证是检查最终文件与计算过程，而非仅听代理说它调用了很多工具。",
    rows=[("通用执行", "文件、程序、资料与工具操作", "输出应是可检查产物，而非操作数量"), ("可修改性", "提示、工具和扩展可调整", "逐项改动，保留最小稳定配置"), ("子代理", "上下级关系与独立配置", "需要明确任务输入、证据和汇总责任"), ("执行环境", "容器或文档支持的环境", "挂载与凭据仍可让任务访问宿主和外部服务"), ("用户干预", "循环中的反馈与扩展节点", "纠正后确认旧计划和新要求已对齐"), ("模型要求", "多轮工具、纠错和代码执行", "小模型是否稳定要通过任务验证")],
    steps=["按官方方式准备运行环境，核对挂载目录与模型配置；使用测试材料，先验证文件输入和结果保存。", "给出一项有明确输出的资料任务，例如整理一批文档并生成索引，说明来源、格式和不能推测的事实。", "检查代理生成的程序与中间结果。统计任务至少用已知样本复算，确认工具执行不是只做形式上的处理。", "需要分工时按材料或职责拆成独立子任务，要求保留证据位置；主任务负责去重、冲突处理和最终结论。", "基础流程稳定后再改提示和扩展，并记录差异。无人值守使用前另测中断、失败和重复执行，确保文件与状态可恢复。"],
    command="text\n资料任务输入建议：\n输入目录只放本次材料；输出另存独立目录。\n要求保留：处理清单、未读成功文件、计算方法、来源索引。\n子代理按独立材料分工，最后由主任务统一去重与核对。",
    task="整理三十份项目会议纪要，按主题生成索引和决策清单。区分已确定、待讨论与互相冲突的内容，保留每条结论的原文位置。",
    acceptance="抽查不同文件与时间段，确认没有把讨论中的建议当作决定。检查程序处理失败的文件是否被悄悄遗漏，以及汇总是否合并了同名但不同项目的事项。",
    tradeoff="适合技术用户处理复杂资料和试验通用代理。丰富的可修改性带来更高排错成本，容器管理也需要基本工程能力。普通写作可以用更轻客户端；明确固定流程可用 Dify；复杂临时任务才更能体现这一类环境的价值。")

add("C04",
    principle="Chatbox 从熟悉的多模型聊天入口出发，逐渐加入真正会操作工作目录的模式。对于报告、翻译和资料讨论，用户可以先不理解复杂代理配置就开始；需要生成文件或执行任务时，再进入 Work／Agent 路线。把两种模式区分清楚，能避免用普通聊天的预期理解具有实际操作能力的工作会话。",
    flow=["桌面聊天／Work 入口\n文件、问题与目标", "会话上下文快照\n身份、偏好和项目说明", "Provider 适配\n所选模型与协议", "对话、文件及记忆材料\n保存与后续使用", "已启用工具与工作目录\n按模式执行", "消息／Agent 循环\n按需加载 Skills"],
    mechanism="稳定的上下文前缀有利于缓存和行为一致，代价是某些全局修改不会自动刷新旧会话。比如你修改报告语气偏好，既有任务仍可能沿用启动时的快照；应检查生效条件，而不是不断强调同一句要求。Skills 按需加载帮助减少提示长度，但文件中的一次性事实应留在项目材料，不能全部塞进长期人格。",
    rows=[("入口难度", "Chat 与 Work／Agent 路线", "先按任务选择是否需要实际工具执行"), ("多模型", "Provider 与协议适配分层", "兼容接口仍需核对参数及工具能力"), ("上下文", "首轮保存一定的上下文快照", "改变规则后检查当前会话是否刷新"), ("工作方法", "Skills 按需加载", "常用写法与一次性事实分开管理"), ("发行边界", "社区源码与商业版本有差别", "功能判断应记录实际版本"), ("成果管理", "对话、文件和目录任务", "打开最终文件检查结构，而不只看聊天预览")],
    steps=["安装适合平台的发行版，在 Chat 中配置一个模型，先验证普通对话、文件输入和历史保存；确认版本所含能力。", "用一份短材料试写报告，明确读者、语气、篇幅和引用要求，检查内容是否遵循原文。", "把反复使用的风格偏好保存到可查看的规则中；改动后用新会话或文档规定的方法确认生效。", "确需读写本地文件或执行步骤时才使用 Work，选择专门工作目录，先做小范围资料整理。", "最终打开导出的文件检查标题、表格和引用，保存事实来源；再把稳定的方法提炼为 Skill，而不是把整段历史当作长期记忆。"],
    command="text\n报告提示示例：\n读者是非技术同事；先解释结论，再说明依据。\n只使用附件中的事实，缺信息时明确标注。\n输出摘要、正文和来源；长期写作偏好与项目事实分开保存。",
    task="根据三份周会记录写一份管理层周报，突出进展、风险和需要决定的事项。不得把计划写成已完成，保留可追溯的来源。",
    acceptance="核对时态、责任人和完成状态，尤其检查模型是否为了行文顺畅补造信息。切换模型时用同一材料比较结构和事实忠实度；启用 Work 后再增加文件保存和格式验证。",
    tradeoff="适合低门槛多模型写作、翻译和轻量目录任务。大量并行工程、持续在线或多人服务不是最自然的起点。与 Cherry 比较工作台和后端需求，与 AnythingLLM 比较是否需要长期资料库，选择自己实际要用的最小复杂度。")
